INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `Emote3`, `Emote4`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `EmoteDelay4`, `RewardText`, `VerifiedBuild`) VALUES
(40397, 0, 0, 0, 0, 0, 0, 0, 0, 'You have removed the taint of demonic influence from this world. Their vile schemes will not come to fruition, take heart in that.', 0),
(40398, 0, 0, 0, 0, 0, 0, 0, 0, 'This has been a long time coming, I would have never imagined this monster would be removed from this world so soon.$B$BYou may have the potential to follow in my footsteps, given your prowess in tracking demons.', 0),
(40399, 0, 0, 0, 0, 0, 0, 0, 0, '<A smirk creeps across Niremius\' face as he glances upward and nods his head..>$B$BAt long last, I have the gemstone. I thank you greatly.', 0),
(40400, 0, 0, 0, 0, 0, 0, 0, 0, 'The Heart of Hazzas. You are more resourceful than I anticipated, $R. Now, as promised, let\'s forge your weapon.', 0),
(40401, 0, 0, 0, 0, 0, 0, 0, 0, 'My work is done, as I have promised, a Glaive worthy of my namesake. Use it well, and keep Azeroth safe.', 0),
(40773, 0, 0, 0, 0, 0, 0, 0, 0, 'Well done, you have proved yourself, maybe now they will leave Felwood, and not return.', 0),
(40774, 0, 0, 0, 0, 0, 0, 0, 0, 'My, these sure are fascinating, full of quite toxic material.$B$BMy benefactors back in Undercity will be pleased, and here, as promised, take these coins.', 0),
(40775, 0, 0, 0, 0, 0, 0, 0, 0, 'You did well.$B$BYou can go now. You are not needed anymore.', 0),
(40776, 0, 0, 0, 0, 0, 0, 0, 0, 'It is quite satisfying to witness the downfall of those who boast about their faith in the Betrayer. They\'ve made a mockery of their legacy by dying at the hands of a paid mercenary.', 0),
(40786, 0, 0, 0, 0, 0, 0, 0, 0, 'The samples are peculiar as they do not exhibit any signs of being twisted by foreign interference or the hands of foul magic. Instead, they appear to be deformed due to primalistic rage.$B$BThere may be a link here that I am not seeing, but I doubt that these samples are connected to what is happening here in Felwood.$B$BRegardless, I appreciate your efforts in ruling out such a possibility.', 0),
(40787, 0, 0, 0, 0, 0, 0, 0, 0, 'For many long years, I have been without the star by my side, but thanks to your efforts, it is now where it rightfully belongs.$B$B<Niremius Darkwind seems lost in the power of the Darkwind Star, his eyes glowing with deep energy.>$B$BYou have performed admirably, young one, and as such, I have prepared a reward for your assistance - one that is truly worthy of your efforts.', 0),
(41070, 0, 0, 0, 0, 0, 0, 0, 0, 'Your act of mercy has granted solace to the tormented treant souls in the Irontree Woods. For that, I am forever grateful.', 0),
(41071, 0, 0, 0, 0, 0, 0, 0, 0, 'I find solace in the belief that the spirits of the creatures we have lost in these dark times have found their way back to the Emerald Dream. There, they may roam freely and peacefully with the great bear spirits Ursoc and Ursol, who watch over the natural balance of our world.$B$BDespite the current state of these lands and the suffering that has occurred, I hold onto the hope that in time, the wounds will heal and the forest will once again be a place of harmony and tranquility.', 0),
(41072, 0, 0, 0, 0, 0, 0, 0, 0, 'I suppose I could find some use for you.', 0),
(41073, 0, 0, 0, 0, 0, 0, 0, 0, 'Please, help me... I have been ambushed by a group of furbolgs. I cannot fail Yohan...', 0),
(41074, 0, 0, 0, 0, 0, 0, 0, 0, 'He entrusted the notes to YOU?$B$B<Yohan snatches them out of your hands and reads them hastily>$B$BIt\'s truly astounding how careless he can be with valuable research conducted on behalf of the Cenarion Circle. Entrusting it to a mere stranger found wandering in the woods... It\'s clear that he lacks the discernment and expertise required to be a part of our order.$B$BYou are dismissed. Thanks for your assistance.', 0),
(41075, 0, 0, 0, 0, 0, 0, 0, 0, 'Morrowgrain? Yes, I\'ve heard of it before.$B$BBut I always assumed it was nothing more than a rumor. However, it seems that there may be more to this mysterious plant than meets the eye.$B$BI\'ve heard whispers that Archdruid Staghelm has been amassing obscene amounts of Morrowgrain for years now. Some say that the plant has sinister properties, and that he has some dark purpose in mind.$B$BWe cannot ignore this. We must get to the bottom of it before it\'s too late. If Staghelm has some nefarious plans, it could put the entire Cenarion Circle at risk.', 0),
(41076, 0, 0, 0, 0, 0, 0, 0, 0, 'I knew it.', 0),
(41077, 0, 0, 0, 0, 0, 0, 0, 0, '<Shandris glances through the notes, and takes a look at the Morrowgrain Seed.>$B$BAs much as I understand your concern, we must approach this matter with caution. The Cenarion Circle has been a long-standing ally of ours, and their mission is to protect and preserve the natural balance of our world. While their methods may seem mysterious to us outsiders, we must trust that they have the best intentions in mind. I fear that Sentinel Briariel might be a bit... overzealous.$B$BFurthermore, we must not forget that there are greater threats looming over us. The Horde has been encroaching on our lands, my Sentinels mutiny, and we cannot afford to be distracted by more internal disputes. Our resources and attention must be focused on defending our home and our people.$B$BI\'m sorry, but this is not enough. For now, the druids in Talonbranch are free to conduct their research in peace.', 0);
INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `CompletionText`, `VerifiedBuild`) VALUES
(40397, 0, 0, 'I grow impatient, have you dispatched the mongrels?', 0),
(40398, 0, 0, 'Each day we must stay vigilant to combat the growing darkness.', 0),
(40399, 0, 0, 'Have you removed this deceitful orc from the world, have you recovered my Gemstone?', 0),
(40400, 0, 0, 'There is taint all across Azeroth, can you feel the world itself calling for aid?', 0),
(40401, 0, 0, 'This will take time.', 0),
(40773, 0, 0, 'So, has the deed been done $R?', 0),
(40774, 0, 0, 'Have you acquired my samples yet?', 0),
(40775, 0, 0, 'Don\'t waste any more time. Get it done, and make sure it\'s done right.', 0),
(40776, 0, 0, 'They deserve no sympathy.', 0),
(40786, 0, 0, 'Has your journey made progress yet?', 0),
(40787, 0, 0, 'With every passing moment, the traitor Faladar comes closer to achieving his vile schemes.', 0),
(41070, 0, 0, 'Despite the stern decree of Yohan, who forbids us from venturing into the treacherous depths of the Irontree Woods, fate has conspired to bring you, an outsider, to our aid. Bound by the laws of our land, Yohan\'s power wanes in the presence of one untethered to our traditions. Yet, I caution you, for his watchful eyes may still cast their gaze upon our endeavors.', 0),
(41071, 0, 0, 'Have you brought peace to these forests?', 0),
(41072, 0, 0, 'Yes, $R?', 0),
(41073, 0, 0, 'The pain... it\'s unbearable...', 0),
(41074, 0, 0, 'Where\'s Marlonias?', 0),
(41075, 0, 0, 'You have returned! Have you found anything in the Talonbranch Grove?', 0),
(41076, 0, 0, 'Poor owls. Have you had any luck finding Morrowgrain seeds?', 0),
(41077, 0, 0, 'Yes?', 0);
