INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(60710, 0, 0, 'I must apologize for lying to you, and using you for power, you must understand, it was all for the greater good of the region.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66424'),
(60710, 1, 0, 'You have given me items of great power, and I will use them to defend this forest until my last breath. Deception can come from all forms, even friends, be wary within the future, and take this as a lesson.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66718'),
(60710, 2, 0, 'Carry my Glaive with conviction, and good luck.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66719');
